"""Discard Yahoo terminal-date overrun bars; preserve every in-scope received pair unchanged."""
from pathlib import Path
import json,gzip,hashlib,datetime as dt
from zoneinfo import ZoneInfo
R=Path(__file__).resolve().parent.parent;ledger=json.loads((R/'audit/market_raw_retention.json').read_text());changed=[]
for item in ledger['sources']:
 path=R/item['path'];payload=json.loads(gzip.decompress(path.read_bytes()));r=payload['chart']['result'][0];zone=ZoneInfo(r['meta']['exchangeTimezoneName']);ts=r['timestamp'];closes=r['indicators']['quote'][0]['close'];assert len(ts)==len(closes)
 pairs=[(ts,value) for ts,value in zip(ts,closes) if dt.datetime.fromtimestamp(ts,zone).date().isoformat()<='2024-07-30'];removed=len(ts)-len(pairs)
 if removed:changed.append({'ticker':item['ticker'],'removed_observation_count':removed,'reason':'Yahoo terminal-date bar overrun removed by exchange-local day; no price kept afterJuly30.'})
 r['timestamp']=[t for t,v in pairs];r['indicators']['quote'][0]['close']=[v for t,v in pairs];retained=json.dumps(payload,ensure_ascii=False,separators=(',',':')).encode();path.write_bytes(gzip.compress(retained,mtime=0));item['retained_uncompressed_sha256']=hashlib.sha256(retained).hexdigest();item['retained_gzip_sha256']=hashlib.sha256(path.read_bytes()).hexdigest();item['historical_timestamp_and_close_arrays_unchanged']=not bool(removed);item['retained_historical_pairs_unchanged']=True;item['removed_out_of_scope_observation_count']=removed;item['retained_last_exchange_local_date']=max(dt.datetime.fromtimestamp(t,zone).date().isoformat() for t,v in pairs)
 path.with_name(path.name.replace('.json.gz','.retention.json')).write_text(json.dumps(item,indent=2))
 p=R/'data'/('yf_'+item['ticker'].replace('^','_').replace('=','_').replace('.','_')+'.json');data=json.loads(p.read_text());data['retained_source_sha256']=item['retained_uncompressed_sha256'];p.write_text(json.dumps(data))
ledger['purpose']='Exact in-scope historical timestamp/close pairs retained for independent replay. API terminal-date overrun pairs and live quote metadata discarded; no later price retained. Original network hashes and clipped retained-byte hashes are explicitly separate.';ledger['terminal_date_clipping']='exchange-local observation day<=2024-07-30, including UTC crypto days';(R/'audit/market_raw_retention.json').write_text(json.dumps(ledger,ensure_ascii=False,indent=2)+'\n');(R/'audit_work/market_retention_correction.json').write_text(json.dumps({'issue':'Independent reviewer found Yahoo terminal-date overrun bars in audit payloads; normalized data and cards were already correctly bounded.','resolution':'Physical audit-array clipping; original source hash retained, derivative hashes rebound; no later-price copy preserved.','changed_responses':changed,'affected_card_values':0},indent=2)+'\n');print('Corrected responses',len(changed),'removedpairs',sum(x['removed_observation_count'] for x in changed))
